<script setup lang="ts">
import { useMessage } from "zenless-ui";
import type { Cosmetic, CosmeticKind, EquippedCosmetic, Profile } from "~/types/entities";
import { resolveErrorMessage } from "~/utils/api-error";

const props = defineProps<{
  kind: CosmeticKind;
  profile: Profile;
}>();

const emit = defineEmits<{
  close: [];
  equipped: [cosmetic: EquippedCosmetic | null];
}>();

const api = useApi();
const message = useMessage();

const cosmetics = ref<Cosmetic[]>([]);
const equippedId = ref<string | null>(null);
const selectedId = ref<string | null>(null);
const loading = ref(true);
const equipping = ref(false);

const kindLabel = computed(() => (props.kind === "title" ? "称号" : "勋章"));

const selectedCosmetic = computed(
  () => cosmetics.value.find((c) => c.documentId === selectedId.value) ?? null,
);

const isSelectionEquipped = computed(() => selectedId.value === equippedId.value);

const rarityClass = (rarity: Cosmetic["rarity"]) => `is-${rarity}`;

const rarityLabel: Record<Cosmetic["rarity"], string> = {
  common: "普通",
  rare: "稀有",
  epic: "史诗",
  legendary: "传说",
  special: "限定",
};

const toThumbUrl = (url: string | null | undefined): string => {
  if (!url) return "";
  if (url.startsWith("blob:") || url.startsWith("data:")) return url;
  if (url.endsWith("-small.webp")) return url;
  return `${url}-small.webp`;
};

const select = (item: Cosmetic) => {
  if (!item.unlocked) return;
  selectedId.value = selectedId.value === item.documentId ? null : item.documentId;
};

const handleConfirm = async () => {
  if (equipping.value) return;
  if (selectedId.value === equippedId.value) {
    message.warning("什么都没改呢！");
    return;
  }
  equipping.value = true;
  try {
    await api.equipCosmetic(props.kind, selectedId.value);
    equippedId.value = selectedId.value;
    const next = selectedCosmetic.value;
    emit(
      "equipped",
      next
        ? {
            documentId: next.documentId,
            name: next.name,
            rarity: next.rarity,
            image: next.image ?? null,
            imageWidth: next.imageWidth,
            imageHeight: next.imageHeight,
          }
        : null,
    );
    message.success(`${kindLabel.value}修改成功`);
  } catch (err) {
    message.error(resolveErrorMessage(err, `修改${kindLabel.value}失败`));
  } finally {
    equipping.value = false;
  }
};

const handleClose = () => emit("close");

const handleOverlayClick = (e: MouseEvent) => {
  if ((e.target as HTMLElement).classList.contains("ik-overlay")) {
    handleClose();
  }
};

const handleKeydown = (e: KeyboardEvent) => {
  if (e.key === "Escape") handleClose();
};

const { acquire, release } = useBodyScrollLock();
const SCROLL_LOCK_TOKEN = Symbol("cosmetics-modal");

onMounted(async () => {
  window.addEventListener("keydown", handleKeydown);
  acquire(SCROLL_LOCK_TOKEN);
  loading.value = true;
  try {
    const result = await api.getMyCosmetics(props.kind);
    cosmetics.value = result.cosmetics;
    equippedId.value = result.equippedDocumentId;
    selectedId.value = result.equippedDocumentId;
  } catch (err) {
    message.error(resolveErrorMessage(err, `获取${kindLabel.value}列表失败`));
  } finally {
    loading.value = false;
  }
});

onBeforeUnmount(() => {
  window.removeEventListener("keydown", handleKeydown);
  release(SCROLL_LOCK_TOKEN);
});
</script>

<template>
  <div class="ik-overlay" @click="handleOverlayClick">
    <div class="ik-overlay__stripe" />
    <div class="ik-cos-dialog">
      <div class="ik-cos-frame">
        <div class="ik-cos-frame__inner">
          <div class="ik-cos-frame__body">
            <!-- Header -->
            <div class="ik-cos-tab-bar">
              <span class="ik-cos-title">修改{{ kindLabel }}</span>
              <button class="ik-cos-close" aria-label="关闭" @click="handleClose">
                <img src="/images/close-btn.webp" alt="关闭" class="ik-cos-close__img" draggable="false" />
              </button>
            </div>

            <div class="ik-cos-main">
              <IkZzzMarquee />

              <div class="ik-cos-grid-wrap">
                <div v-if="loading" class="ik-cos-grid-loading">
                  <i class="z-icon-loading ik-spin" /> 加载中...
                </div>
                <div v-else-if="!cosmetics.length" class="ik-cos-grid-empty">
                  暂无{{ kindLabel }}，等活动开启后再来看看吧
                </div>
                <z-scrollbar v-else class="ik-cos-grid-scroll">
                  <!-- 卸下选项 -->
                  <div class="ik-cos-grid">
                    <button
                      type="button"
                      class="ik-cos-item ik-cos-item--none"
                      :class="{ 'is-selected': selectedId === null }"
                      @click="selectedId = null"
                    >
                      <span class="ik-cos-item__none-text">不展示</span>
                    </button>
                    <button
                      v-for="item in cosmetics"
                      :key="item.documentId"
                      type="button"
                      class="ik-cos-item"
                      :class="[
                        rarityClass(item.rarity),
                        {
                          'is-selected': selectedId === item.documentId,
                          'is-equipped': equippedId === item.documentId,
                          'is-locked': !item.unlocked,
                        },
                      ]"
                      :title="item.unlocked ? item.name : `解锁条件：${item.conditionDescription}`"
                      @click="select(item)"
                    >
                      <div class="ik-cos-item__thumb">
                        <img v-if="item.image" :src="toThumbUrl(item.image)" :alt="item.name" class="ik-cos-item__img" />
                        <span v-else class="ik-cos-item__placeholder">{{ item.name.charAt(0) }}</span>
                        <span v-if="!item.unlocked" class="ik-cos-item__lock">
                          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="11" width="16" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/></svg>
                        </span>
                      </div>
                      <span class="ik-cos-item__name">{{ item.name }}</span>
                      <span class="ik-cos-item__rarity">{{ rarityLabel[item.rarity] }}</span>
                      <span v-if="!item.unlocked" class="ik-cos-item__cond">{{ item.conditionDescription }}</span>
                      <i v-if="equippedId === item.documentId" class="z-icon-success ik-cos-item__badge" />
                    </button>
                  </div>
                </z-scrollbar>
              </div>

              <!-- 详情预览条 -->
              <div class="ik-cos-detail">
                <template v-if="selectedCosmetic">
                  <strong class="ik-cos-detail__name">{{ selectedCosmetic.name }}</strong>
                  <span v-if="selectedCosmetic.description" class="ik-cos-detail__desc">{{ selectedCosmetic.description }}</span>
                  <span v-else class="ik-cos-detail__desc ik-cos-detail__desc--empty">{{ selectedCosmetic.unlocked ? "已解锁，可装备展示" : `解锁条件：${selectedCosmetic.conditionDescription}` }}</span>
                </template>
                <template v-else>
                  <strong class="ik-cos-detail__name">不展示{{ kindLabel }}</strong>
                  <span class="ik-cos-detail__desc ik-cos-detail__desc--empty">主页将不显示{{ kindLabel }}</span>
                </template>
              </div>

              <div class="ik-cos-submit-wrap">
                <z-button
                  class="ik-cos-submit"
                  :disabled="loading || equipping || isSelectionEquipped"
                  @click="handleConfirm"
                >
                  {{ equipping ? '保存中...' : '确定' }}
                </z-button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

